SELECT r.request_id,r.created_at,to_jsonb(r)->>'updated_at' AS updated_at,r.status AS request_status,f.name AS facility_name,p.payment_id,p.payment_status,b.name AS confirmed_booking_id,b.booking_status,b.approval_status,b.payment_status AS booking_payment_status FROM public."SSP_Facility_Booking_Request" r LEFT JOIN public."SSP_Payment" p ON p.pay_rec_id=r.payment LEFT JOIN public."SSP_Facility" f ON f.id=r.facility LEFT JOIN public."SSP_Facility_Booking" b ON b.payment=r.payment WHERE lower(trim(r.status)) IN ('cancelled','canceled') OR lower(trim(p.payment_status)) IN ('cancelled','canceled') ORDER BY COALESCE(NULLIF(to_jsonb(r)->>'updated_at','')::timestamptz,r.created_at) DESC NULLS LAST LIMIT 5;